import java.util.ArrayList;
import java.util.List;

public class Solution {
  private static int initialValueHolder;
  private static int[] commitT, finishT, valueT, outcomeT;

  public static int[] atIsolationView(int initialValue, int maxWaitTicks, int[] readTick, int[] readKind,
                                      int[] txCommitTick, int[] txFinishTick, int[] txValue, int[] txOutcome) {
    if (initialValue < 0) throw new IllegalArgumentException("value must be non-negative");
    if (maxWaitTicks < 0) throw new IllegalArgumentException("max wait must be non-negative");
    if (readTick == null || readKind == null || txCommitTick == null || txFinishTick == null
        || txValue == null || txOutcome == null) throw new IllegalArgumentException("array length mismatch");
    if (readTick.length != readKind.length) throw new IllegalArgumentException("array length mismatch");
    if (txCommitTick.length != txFinishTick.length || txCommitTick.length != txValue.length
        || txCommitTick.length != txOutcome.length) throw new IllegalArgumentException("array length mismatch");
    for (int i = 0; i < readTick.length; i++) {
      if (readTick[i] < 0) throw new IllegalArgumentException("negative tick");
      if (readKind[i] != 0 && readKind[i] != 1) throw new IllegalArgumentException("read kind must be 0 or 1");
      if (i > 0 && readTick[i] <= readTick[i - 1]) throw new IllegalArgumentException("read ticks must increase");
    }
    for (int i = 0; i < txCommitTick.length; i++) {
      if (txCommitTick[i] < 0 || txFinishTick[i] < 0) throw new IllegalArgumentException("negative tick");
      if (txValue[i] < 0) throw new IllegalArgumentException("value must be non-negative");
      if (txOutcome[i] != 0 && txOutcome[i] != 1) throw new IllegalArgumentException("outcome must be 0 or 1");
      if (txFinishTick[i] <= txCommitTick[i]) throw new IllegalArgumentException("finish must be after commit");
    }
    for (int i = 1; i < txCommitTick.length; i++) {
      boolean disjoint = txCommitTick[i] >= txFinishTick[i - 1] || txCommitTick[i - 1] >= txFinishTick[i];
      if (!disjoint) throw new IllegalArgumentException("overlapping global locks");
    }
    initialValueHolder = initialValue;
    commitT = txCommitTick; finishT = txFinishTick; valueT = txValue; outcomeT = txOutcome;
    int n = commitT.length;

    List<Integer> out = new ArrayList<>();
    for (int r = 0; r < readTick.length; r++) {
      int t = readTick[r];
      if (readKind[r] == 1) {
        int cur = t;
        boolean waited = false;
        boolean timedOut = false;
        for (int guard = 0; guard <= n; guard++) {
          int h = holder(cur);
          if (h < 0) break;
          cur = finishT[h];
          waited = true;
          if (cur - t > maxWaitTicks) { timedOut = true; break; }
        }
        if (timedOut) { out.add(-1); out.add(4); continue; }
        out.add(valueAt(cur));
        out.add(waited ? 2 : 0);
      } else {
        int p = producer(t);
        out.add(valueAt(t));
        if (p < 0) { out.add(0); }
        else if (finishT[p] > t) { out.add(outcomeT[p] == 1 ? 3 : 1); }
        else { out.add(0); }
      }
    }
    int[] res = new int[out.size()];
    for (int i = 0; i < out.size(); i++) res[i] = out.get(i);
    return res;
  }

  /** 时刻 t 谁持有全局锁：已本地提交（一阶段）但全局事务还没二阶段结束的那个分支。 */
  private static int holder(int t) {
    for (int i = 0; i < commitT.length; i++) if (commitT[i] <= t && t < finishT[i]) return i;
    return -1;
  }

  /** 本地已提交视图：commitTick <= t 的最后一个分支的写入值；它若已终审回滚则继续往前退。 */
  private static int valueAt(int t) {
    int p = producer(t);
    if (p < 0) return initialValueHolder;
    if (outcomeT[p] == 0 || finishT[p] > t) return valueT[p];
    return valueAt(commitT[p] - 1);              // 回滚后：退回写入之前的样子
  }

  private static int producer(int t) {
    int best = -1;
    for (int i = 0; i < commitT.length; i++) {
      if (commitT[i] <= t && (best < 0 || commitT[i] > commitT[best])) best = i;
    }
    return best;
  }
}

